function eA_preproc_blink(cfg)%% preprocessing function% assign the value of cfg.dataset to the variable datasetdataset = cfg.dataset;PREOUT_FIG = cfg.PREOUT_FIG;PREOUT_CLEAN = cfg.PREOUT_CLEAN;SUBJ = cfg.SUBJ;cfg=[];                                     % initialize empty configuration structurecfg.dataset = dataset;                      % previously defined dataset variable assigned to the dataset field of the cfg structurecfg.channel = 'all';                        % sets channel field of the cfg structure to all, use all channelscfg.continuous = 'yes';                     % specifies that data is continuousdata = ft_preprocessing(cfg);               % calls FieldTrip function using cfg as argument, perform preprocessing on data and save as such using the cfg structure                                             % look at the dataset using ft_data_browser(cfg,data)%% Step 1: Linenoise removal Toolbox by Klugedisp 'zapline-plus-main'                    % display string "" in the command windowcfg=[];                                     % initialize empty configuration structurecfg.resample = 'yes';                       % data should be resampledcfg.resamplefs = 350;                       % data sampling rate changed to 350Hzcfg.detrend = 'no';                         % no detrending (removes trends and slow variations in the data)data = ft_resampledata(cfg, data);          % uses the function resample on the data and saves this as data (change in data due to analysis)dat = data.trial{1}(:,:);                   % select all rows from beginning to the third-to-last row; dat is now a numeric matrix: channels x time points% call the zapline-function[zaplineData, zaplineConfig, analyticsResults, plothandles] = clean_data_with_zapline_plus(dat, data.fsample, 'noisefreqs', 50);    % custom function passing cleaning parameters through it                                                                                                                                    % dat - EEG data matrix from earlier                                                                                                                                    % data.fsample - original sampling rate (350Hz)                                                                                                                                    % noisefreqs, 50 - specify 50Hz as noise frequency to removesaveas(gcf, fullfile(PREOUT_FIG, 'figures',  sprintf('%s_zapline-plus_50Hz.png', SUBJ)) )       % Saves figures in path of PREOUT in folder figuresdata.trial{1} = zaplineData;                                                                    % replaces original noisy channels with cleaned dataft_postamble previous   data                                                                    % this copies the data.cfg structure into the cfg.previous field. You can also use it for multiple inputs, or for "varargin"ft_postamble history    data                                                                    % this adds the local cfg structure to the output data structure, i.e. dataout.cfg = cfgplotit=1;                                                                   % plot it 1 = TRUEif plotit                                                                       disp 'check if zapline did well'                                        % message in command window    cfgfreq              = [];                                              % initializes empty cfg structure    cfgfreq.output       = 'pow';                                           % output should be power    %   cfgfreq.channel      = 'all'; still applied to all channels    cfgfreq.method       = 'mtmfft';                                        % multi-taper method with Fourier transform    cfgfreq.taper        = 'hanning';                                       % reduce spectral leakage and smooths data; hanning window taper    cfgfreq.keeptrials   = 'no';                                            % Use the spectrum and not individual trials    cfgfreq.foilim       = [0 min(256/2, 200)];                             % frequencies of interest 0Hz to half of 256Hz(128Hz) or 200Hz    cfgfreq.pad='nextpow2';                                                 % Zero-padding to increase resolution    tempfreq = ft_freqanalysis(cfgfreq, data);                              % perform frequency analysis using ft_function on data    figure; semilogy(tempfreq.freq, mean(tempfreq.powspctrm(1:end-3,:)))    % plots the average power spectrum across all but last 3 channels on a semilog y-axis    clear tempfreq                                                          % remove the variable tempfreq from the workspaceend%% Step 2: High-pass filterdisp('high pass filter the data')                                           % message in command windowcfg=[];                                                                     % initialize cfg structure cfg.hpfilter = 'yes';                                                       % high pass filter should be appliedcfg.hpfreq =  0.5;                                                          % everything above 0.5Hz is passed, below 0.5Hz is filteredcfg.hpfiltord = 4;                                                          % order of the filter, higher orders mean steeper cutoff, determines the slopecfg.continuous = 'yes';                                                     % data should be treated as continuousdata = ft_preprocessing(cfg, data);                                         % apply high-pass filter on data using ft_preprocessing%% Step 3: Rereference Vert EOG to each othercfg = [];                                                                   % initialize emtpy cfg structurecfg.channel    = {'VEOG1', 'VEOG2'};                                        % specify channels of interestcfg.reref      = 'yes';                                                     % enables re-referencingcfg.refchannel = 'VEOG1';                                                   % calculate the signal relative to a specific reference channel (in this case VEOG1)data_eogvert      = ft_preprocessing(cfg, data);                            % apply rereferencing via ft_preprocessing and data_eogvert is the outputdata_eogvert.label{2} = 'EOGV';                                             % name this new reference channel EOGVcfg = [];                                                                                                                      cfg.channel = 'EOGV';data_eogvert   = ft_preprocessing(cfg, data_eogvert);                       % extract the channel EOGV from the data and name it data_eogvert%% Step 3.1: Detect blinks using ft_artifact_eog (from the EOGV channel)% Define configuration for blink detection using ft_artifact_eogcfg = [];                                                                   % initialize cfg structurecfg.continuous = 'yes';                                                     % Treat the data as continuouscfg.artfctdef.eog.channel = 'EOGV';                                         % Channel for vertical EOG (after re-referencing)cfg.artfctdef.eog.bpfilter = 'yes';                                         % Apply bandpass filter for EOG artifact detectioncfg.artfctdef.eog.bpfreq = [1 15];                                          % Typical blink frequency rangecfg.artfctdef.eog.hilbert = 'yes';                                          % Use Hilbert transform for detectioncfg.artfctdef.eog.cutoff = 2;                                               % Z-value threshold for detecting blinkscfg.artfctdef.eog.feedback = 'yes';                                         % Provide visual feedback% cfg.artfctdef.zvalue.trlpadding = 0;                                      % No trial padding% cfg.artfctdef.zvalue.fltpadding = 0.1;                                    % Filter padding to avoid edge artifacts% cfg.artfctdef.zvalue.artpadding = 0.1;                                    % Padding around the detected artifact% cfg.artfctdef.zvalue.interactive = 'no';                                  % Set to 'yes' for manual interaction% Check the data formatif isfield(data_eogvert, 'trial') && isfield(data_eogvert, 'label') && isfield(data_eogvert, 'fsample')     % checks for trial, label and fsample    [cfg, artifact] = ft_artifact_eog(cfg, data_eogvert);                                                   % use function ft_artifact_eog on data_eogvert and make a new artifact variable    disp('Detected blink events:');                                         % display detected blink events    disp(artifact);                                                         % display artifactselse    error('The input data is not in the expected FieldTrip format.');       % if there are none display this error messageend%% Step 3.2: Redefine Trials Around Blink Events%  Set parameters which should later be put into a matrix (trl)pre_blink_time = -1.5*data.fsample;                                         % time before blink (in seconds) converted into samples -1.5*350=-525post_blink_time = 1.5*data.fsample;                                         % Time after blink (in seconds) converted into samples 1.5*350=525blink_amplitude_threshold = 100;                                            % Define a threshold for detecting blinks (adjust this based on your data)% Ensure that 'artifact' contains time points of blink events.% Assuming 'artifact' is a matrix where rows represent trials or blinks.blink_trial_all = round(mean(artifact, 2));                                 % define blink_trial as the mean time point of the artifact (which is represented as the range -1.5 to 1.5)blink_trial_all = sort(blink_trial_all);                                    % sort blink_trial to ensure it´s in chronological order%% Step: 3.3: Use a distance between blinks of 3s blink_trial_distance_1050 = 1050;                                                               % Minimum distance between trials in samples (350Hz = 1s)blink_trial_1050 = blink_trial_all([true; diff(blink_trial_all) > blink_trial_distance_1050]);  % redefine them blink_trial_1050% Initialize trl matrixtrl = [];                                                                   % Initialize empty trl matrixtrl(:, 1) = blink_trial_1050 + pre_blink_time;                              % Start of trialtrl(:, 2) = blink_trial_1050 + post_blink_time;                             % End of trialtrl(:, 3) = pre_blink_time;                                                 % Determines the offeset of each trial, needs to know where time 0s in each trial istrl = trl(trl(:, 1) > 0, :);                                                % Remove invalid trials (start of trial must be positive)% Define the trials based on 'trl'cfg = [];                                                                   % Initialize empty cfg structurecfg.trl = trl;                                                              % assing trl matrix to cfg structuredata_trials = ft_redefinetrial(cfg, data);                                  % extract segments in data based on the start and end points in cfg.trl% Calculate the mean amplitude, peak amplitude, and blink durations for each trialblink_mean_amplitudes = zeros(size(trl, 1), 1);                             % Preallocate array for storing means in trl matrix with zero (Platzhalter)blink_peak_amplitudes = zeros(size(trl, 1), 1);                             % Preallocate array for storing peaksblink_durations = zeros(size(trl, 1), 1);                                   % Preallocate array for blink durationsfor i = 1:size(trl, 1)    % Extract the trial data    trial_data = data_trials.trial{i};  % Access the ith trial    % Calculate the mean amplitude of the trial    blink_mean_amplitudes(i) = mean(abs(trial_data(:)));                    % Mean of absolute amplitudes    % Calculate the peak amplitude of the trial    blink_peak_amplitudes(i) = max(abs(trial_data(:)));                     % Peak of absolute amplitudes    % Detect blink onset and offset by thresholding    blink_indices = find(abs(trial_data) > blink_amplitude_threshold);      % Find indices where the blink occurs    if ~isempty(blink_indices)        % Calculate blink duration (in samples)        blink_duration_samples = blink_indices(end) - blink_indices(1);        % Convert to time (seconds)        blink_durations(i) = blink_duration_samples / data.fsample;    else        % If no blink detected, set duration to 0        blink_durations(i) = 0;    endend% Append the mean amplitude, peak amplitude, and blink duration to the trl matrixtrl(:, 4) = blink_mean_amplitudes;trl(:, 5) = blink_peak_amplitudes;trl(:, 6) = blink_durations;% Add the trl matrix to cfg structurecfg.trl = trl;% Debug output to confirm trl is correctly assigneddisp('trl field being assigned to cfg:');disp(cfg.trl);                                                              % Display the trl for confirmation%% Step 3.4: Use a distance of 1s = 1/350 between blinksblink_trial_distance_350 = 350;blink_trial_350 = blink_trial_all([true; diff(blink_trial_all) > blink_trial_distance_350]);blink_trial_mean_peak_length_350 = [];blink_trial_mean_peak_length_350(:, 1) = blink_trial_350 + pre_blink_time;blink_trial_mean_peak_length_350(:, 2) = blink_trial_350 + post_blink_time;blink_trial_mean_peak_length_350(:, 3) = pre_blink_time;blink_trial_mean_peak_length_350 = blink_trial_mean_peak_length_350(blink_trial_mean_peak_length_350(:, 1) > 0, :);assignin('base', 'blink_trial_mean_peak_length_350', blink_trial_mean_peak_length_350);                   % Store blink_trial_mean_peak_length_350 in workspace% Append the columns from `trl` to `data_trials.cfg.trl`data_trials.cfg.trl = [data_trials.cfg.trl, trl(:, 4:end)];% Verify the updated `trl` matrix in the cfg structuredisp(size(data_trials.cfg.trl));% Check and clean trial_info after defining trialsif exist('trl', 'var')    trl = trl(~any(isnan(trl), 2), :); % Remove rows with NaNs    disp('Cleaned trl by removing rows with NaNs.');end%% Step 4: Muscle artifact detection using ft_artifact_musclecfg = [];                                                                   % Initialize an empty cfg structurecfg.continuous = 'yes';                                                     % Data is continuouscfg.trl = trl% Treat the data as continuous% You can also set to EEG than only applied on EEG channelscfg.artfctdef.muscle.channel = setdiff(data.label, {'VEOG1', 'VEOG2', 'HEOG1', 'HEOG2'});   % Exclude specified channelscfg.artfctdef.muscle.inspect = setdiff(data.label, {'VEOG1', 'VEOG2', 'HEOG1', 'HEOG2'});   % Channels to inspect, excluding EOG channels  % Specify channels to analyze for muscle artifactscfg.artfctdef.muscle.bpfilter = 'yes';                                                      % Enable bandpass filtering to isolate muscle frequenciescfg.artfctdef.muscle.bpfreq = [80 100];                                                     % Frequency range typical for muscle artifactscfg.artfctdef.muscle.bpfiltord = 4;                                         % Order of the filtercfg.artfctdef.muscle.hilbert = 'yes';                                       % Use Hilbert transform to detect amplitudecfg.artfctdef.muscle.threshold = 4;                                         % Threshold value (adjust as needed based on your data)cfg.artfctdef.muscle.feedback = 'yes';                                      % Show feedback during artifact detectioncfg.artfctdef.muscle.boxcar = 0.2;                                          % Width of the moving average boxcarcfg.artfctdef.muscle.cutoff = 20;                                           % Z-value threshold for detecting muscle artifacts% Detect muscle artifacts[cfg, artifact_muscle] = ft_artifact_muscle(cfg, data_trials);% Save the columns mean, peak and lengthblink_mean_peak_length_1050 = data_trials.cfg.trl(:, 4:end);% Reject the muscle artifacts from datacfg = [];cfg.artfctdef.reject = 'complete';                                          % Reject complete segments containing muscle artifactscfg.artfctdef.muscle.artifact = artifact_muscle;                            % Assign detected artifacts for rejectiondata_trials = ft_rejectartifact(cfg, data_trials);% Restore original trl columns for remaining trialsblink_trials_remaining= ismember(trl(:, 1), data_trials.sampleinfo(:, 1));data_trials.cfg.trl = trl(blink_trials_remaining, :);% % Redefine trials on cleaned data% cfg = [];% cfg.trl = trl;                                                            % Use the trl matrix from earlier step% data_trials = ft_redefinetrial(cfg, data_trials);                         % Segment trials from cleaned data%% Step 5: Perform ICAdisp 'Run ICA'cfg = [];cfg.channel = 'all';cfg.method = 'runica';cfg.runica.stop = 0.00000014;                                               % minimum amount of change, stop iterating at this value (threshold) comp = ft_componentanalysis(cfg, data_trials);% Step 5.1: Visualize the time course of the ICA componentscfg = [];cfg.viewmode = 'vertical';                                                  % Set the view mode to vertical for easier inspection of componentscfg.channel = [1:60];                                                         % Specify the components to viewft_databrowser(cfg, comp);                                                  % Open the data browser to visualize the components% Step 5.2: Plot the spatial topography of the ICA componentscfg = [];cfg.component = [1:60];                                                     % Specify the components to plotcfg.layout = 'EEG1010';                                                     % Adjust based on your system (e.g., 'EEG1010' for EEG)cfg.viewmode = 'component';cfg.comment = 'no';cfg.marker = 'off';figure('units', 'normalized', 'outerposition', [0 0 1 1]);                  % Full-screen figure windowft_topoplotIC(cfg, comp);% Step 5.3: Prompt for manually specified components to rejectmanual_reject_input = input('Enter components to reject (e.g., 1, 2, 4):');if ~isempty(manual_reject_input)    % Convert input to numeric array    manual_reject = str2num(manual_reject_input{1});else    manual_reject = [];  % No components to reject if input is emptyend% Step 5.4: Reject specified components and reconstruct datacfg = [];cfg.component = manual_reject;  % Manually specified componentsdata_clean = ft_rejectcomponent(cfg, comp, data_trials);% Step 5.5: Save the cleaned dataoutput_filename = fullfile(PREOUT_CLEAN, sprintf('%s_cleaned_data.mat', SUBJ));save(output_filename, 'data_clean', '-v7.3');disp(['Cleaned data saved to: ' output_filename]);% % Step 5.6: Manually specify components to reject (e.g., 1, 2, 4, 7, 17)% manual_reject = inputdlg('enter components') % specify the type of data% Preserve trial information (trl) for potential future useif isfield(data_trials.cfg, 'trl')    data_clean.cfg.trl = data_trials.cfg.trl;else    warning('No trial information (trl) found in data_trials.cfg.');end% Save preprocessed data to use in future functionsoutput_filename = fullfile(PREOUT_CLEAN, sprintf('%s_cleaned_data.mat', SUBJ));save(output_filename, 'data_clean', '-v7.3');disp(['Cleaned data saved to: ' output_filename]);% end% % Prepare to call the third script%cfg=[];% Definition of variables in the workspace% analyticsResults -> Part of Zapline-Plus% artifact -> EOG artifact% artifact_muscle -> muscle artifact% blink_amplitude_threshold -> Definition of blink amplitude% blink_duration_sample -> calculates the length of the blink% blink_durations -> blink length matrix for 3s interval% blink_indices -> may be important for onset and offset of the blink% blink_mean_amplitudes -> mean amplitude of blink for 3s interval% blink_peak_amplitudes -> mean peak amplitude of blink for 3s interval% blink_trial_all -> all the blink trials in the continuous EEG% blink_mean_peak_length -> blink properties% blink_trial_distance_1050 -> 3s distance between each blink% blink_trial_distance_350 -> 1s distance between each blink% blink_trial_1050 -> all trials with a distance of 3s% blink_trial_350 -> all trials with a distance of 1s% blink_trials_remaining -> are all those that remain after the muscle% artifact rejection% cfg -> cfg structure% cfg -> Part of Zapline-Plus% zaplineData -> Part of Zapline-Plus% comp -> Components of ICA% dat -> Part of Zapline-Plus% data -> raw data% data_clean -> final data after all preprocessing% data_eogvert -> new dataset consisting the vertical eye-channels to% where to identify blinks and redefine trials% data_trials -> reduced data to the trial events% dataset -> path where the raw data are stored% i -> index?% manual_reject = displays the components that are rejected% manual_reject_input = displays the components that are rejected% output_filename -> Where the output should be% plothandles -> Part of Zapline-Plus% plotit -> Part of Zapline-Plus% post_blink_time -> 1.5s after the blink event% pre_blink_time -> -1.5s before the blink event% PREOUT -> for the Zapline figures% PREOUT_CLEAN -> for the cleaned data% Possible Code for later% Reload data_clean to confirm% loaded_data = load(output_filename);% if isfield(loaded_data.data_clean.cfg, 'trl')%     disp('trl field successfully saved in data_clean.');% else%     warning('trl field is missing in saved data_clean.');% end